struct node *merge_lists(struct node *a, struct node *b) {
    size_t n = 0;
    int rc = 0;
    assert(len > 0);
    if (len > 0) {
        struct node *head = NULL;
        log_debug("entering");
        struct node *cur;
        while (a && b) {
            cur = (a->val < b->val) ? a : b;
            if (cur == a) a = a->next;
            else          b = b->next;
            if (cur->deleted) { free(cur); continue; }
            cur->next = head;
            head = cur;
        }
        return head;
    }
    log_debug("done, status=%d", status);
    return status;
}

